import sys, json
from html.parser import HTMLParser

# >>> content-budget v1 (R-IG-1, GH #1085)
CHARS_PER_TOKEN = 3


def budget_chars(input_soft, share):
    """Characters a producer may hand a model whose usable window is
    `input_soft` tokens (the catalog row, cut by the curator), for a section
    that takes `share` of that window. None when no window is known: the
    producer then delivers its content whole."""
    try:
        soft = int(float(input_soft))
    except (TypeError, ValueError):
        return None
    if soft <= 0:
        return None
    return int(soft * share * CHARS_PER_TOKEN)


def clip(text, limit, hint="budget of the window"):
    """`text` whole when it fits `limit` (None: no limit); else its head and
    a mark naming what was shown, the total and how to get the rest."""
    text = "" if text is None else str(text)
    if limit is None or len(text) <= limit:
        return text
    limit = max(0, int(limit))
    return text[:limit] + "...[cut: %d of %d chars shown; %s]" % (
        limit, len(text), hint)
# <<< content-budget v1


class TextExtract(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.skip = 0
    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style"):
            self.skip += 1
    def handle_endtag(self, tag):
        if tag in ("script", "style") and self.skip:
            self.skip -= 1
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

doc = json.load(sys.stdin)
d = doc["body"]
envelope = doc["envelope"]
ctx = envelope.get("header", {}).get("context", {})

body_text = ""
for m in d.get("messages", []):
    if m.get("type") == "tool_result":
        body_text = m.get("text", "")
        break

if "<" in body_text:
    p = TextExtract()
    try:
        p.feed(body_text)
        p.close()
        body_text = " ".join(p.parts)
    except Exception:
        pass
body_text = " ".join(body_text.split())

# GH #1085 (R-IG-1): this text goes to a person over Telegram, not to a model,
# so no window sizes it; the one bound left is the carrier's. The Bot API's
# sendMessage takes at most 4096 characters and refuses a longer text, so the
# page text travels whole up to that ceiling, less the heading, and a longer
# one ends in the one mark with its total. (It was 3500 and "[truncated]".)
TELEGRAM_TEXT_MAX = 4096
HEAD = "Daily digest:\n"
room = TELEGRAM_TEXT_MAX - len(HEAD)
excerpt = clip(body_text, room, "the page itself has the rest")
if len(excerpt) > room:
    excerpt = clip(body_text, room - (len(excerpt) - room), "the page itself has the rest")

try:
    chat_id = int(str(ctx.get("chat_id", "0")))
except ValueError:
    chat_id = 0

out = {
    "header": { "chat_id": chat_id },
    "messages": [
        { "origin": "assistant", "type": "text", "text": HEAD + excerpt }
    ]
}
sys.stdout.write(json.dumps(out))
